/* ── extras 문자열 → 객체 ── */
const TYPE = { video: ['video', '🎥', ['concept', 'motivate']], q: ['fun_question', '💡', ['concept', 'basic_problem']], tip: ['tip', '🧩', ['concept', 'misconception']], real: ['real_world', '🌍', ['real_world', 'summary']], game: ['game', '🎮', ['leveled_problem', 'offline_activity']], x: ['misconception', '⚠️', ['misconception', 'basic_problem']], e: ['example', '📝', ['concept', 'offline_activity']], c: ['checklist', '✅', ['next_lesson']] };
const PFX = { video: 'v', q: 'q', tip: 't', real: 'r', game: 'g', x: 'x', e: 'e', c: 'c' };
function extras(n, list) {
  const cnt = {};
  return list.map(line => {
    const p = line.split('|'); const k = p[0]; cnt[k] = (cnt[k] || 0) + 1; const [type, icon, fit] = TYPE[k];
    const id = PFX[k] + '_l' + n + '_' + cnt[k];
    if (k === 'video') return { id, type, icon, title: p[1], url: 'https://www.youtube.com/results?search_query=' + encodeURIComponent(p[2]).replace(/%20/g, '+'), description: p[3], source: '유튜브 검색 (교사 사전 확인 권장)', fit_slides: fit };
    return { id, type, icon, title: p[1], content: p[2], fit_slides: fit };
  });
}
// 「결」 낱말 거르기 — 원문 「결과」「해결」을 화면에 두지 않는다
const nk = (s) => String(s).replace(/계산 결과가/g, '계산한 값이').replace(/결과가/g, '값이').replace(/결과는/g, '값은').replace(/결과를/g, '값을').replace(/문제를 해결해요/g, '문제를 풀어요').replace(/어떻게 해결했나/g, '어떻게 풀었나').replace(/해결/g, '풀이');
const lines = (t) => String(t).replace(/([다요])\. /g, '$1.\n').trim();
const clone = (o) => JSON.parse(nk(JSON.stringify(o)));
// 물음 끝맺음 — 원문 「~은?」「~까?」를 학생 말씨(요)로
function qfix(q) {
  return q.replace(/몫은\?$/, '몫은 얼마일까요?').replace(/계산하면\?$/, '계산하면 얼마일까요?').replace(/나타내면\?$/, '나타내면 얼마일까요?').replace(/옮기면\?$/, '옮기면 얼마일까요?')
    .replace(/양은\?$/, '양은 얼마일까요?').replace(/까닭은\?$/, '까닭은 무엇일까요?').replace(/것은\?$/, '것은 무엇일까요?').replace(/수는\?$/, '수는 무엇일까요?')
    .replace(/\*\*까닭\*\*은\?$/, '**까닭**은 무엇일까요?').replace(/까\?$/, '까요?').replace(/\*\*(\S+)\*\*을까\?/, '**$1**을까요?');
}
function problemData(p, title, body, fig) {
  const d = { title, scenario: { icon: '🔢', body }, question: nk(qfix(p.q)) };
  if (fig) d.fig = fig;
  const hint = (p.hints || []).join(' ').replace(/<\/?strong>/g, '**');
  if (p.opts) { d.options = p.opts.map((t, i) => (i === p.ci ? { text: nk(t), correct: true } : { text: nk(t) })); d.note = nk('풀이: ' + hint + ' → **' + p.opts[p.ci] + '**'); }
  else { d.input = 'count_input'; d.answer = +p.a; d.note = nk('풀이: ' + hint + ' → **' + p.a + '**'); }
  return d;
}

const LESSONS = {};
const keys = Object.keys(T);
keys.forEach((key, idx) => {
  const t = T[key], s = SK[key] ? SRC[SK[key]] : null, n = idx + 1;
  const ex = extras(n, t.ex); const id = (k, i) => ex.filter(e => e.id.startsWith(PFX[k] + '_l' + n + '_'))[i - 1].id;
  const prevItems = idx === 0 ? PREV0 : T[keys[idx - 1]].exit;
  const slides = []; const srcNotes = {};   // 지도서 직행 개념 장의 근거 쪽 — 무대가 그리지 않는 칸이라 장(data)이 아니라 meta 에 둔다(test_stage2 「안 그리는 데이터 필드 0」)
  const add = (block, stage, data, sug, tn) => { const sl = { id: 's' + String(slides.length + 1).padStart(2, '0'), stage, block, data }; if (tn) data.tnote = tn; sl.suggested_extras = sug || []; slides.push(sl); };
  add('cover', '도입', { title: t.cover[0], emoji: t.cover[1] }, [id('video', 1)]);
  const rv = { title: idx === 0 ? '지난 단원에서 배운 것, 기억나요?' : '지난 시간엔 무엇을 했나요?', content: t.review, items: prevItems.map(x => ({ q: x.q, a: x.a })) };
  if (idx > 0) rv.from = keys[idx - 1]; else if (U5 && U5.u5_l10) rv.from = PREV_KEY; else rv.content += ' (지도서 진단 평가 문항으로 되짚어요.)';
  add('review', '도입', rv, [id('q', 1)]);
  add('motivate', '도입', { scene_title: t.mot.t, desc: t.mot.desc, question: t.mot.q, img: 'assets/photo/math/' + t.mot.img + '.jpg' }, [id('q', 2), id('real', 1)], t.mot.tn);
  const csug = [[id('e', 1)], [id('tip', 1)], [id('e', 2), id('tip', 2)], [id('q', 3)]];
  t.con.forEach(([si, tn, fig], i) => {
    let title, content;
    if (typeof si === 'number') { const src = s.slides[si]; title = nk(src.title); content = nk(lines(src.text)); } else { title = si.t; content = si.x; }
    const d = { fig: clone(fig), title, content }; if (typeof si !== 'number') srcNotes['s' + String(slides.length + 1).padStart(2, '0')] = si.g;
    add('concept', '전개', d, csug[i], tn);
  });
  add('misconception', '전개', { title: '이런 생각을 조심해요', label: '자주 하는 생각', wrong: t.mis[0], right: t.mis[1], hint: t.mis[2] }, [id('x', 1), id('x', 2)], t.mis[3]);
  const bsug = [[id('tip', 3)], [id('e', 3)], [id('q', 4)]];
  t.basic.forEach(([pi, body, fig], i) => add('basic_problem', '기본문제', problemData(typeof pi === 'number' ? s.problems[pi] : pi, '기본 문제 ' + '①②③'[i], body, fig ? clone(fig) : null), bsug[i]));
  add('leveled_problem', '기본문제', { title: '수준을 골라 풀어요', levels: t.lev }, [id('q', 5), id('game', 1)], t.levTn);
  add('offline_activity', '응용문제', { title: t.act.t, type: t.act.type, goal: t.act.goal, steps: t.act.steps, solo: t.act.solo, materials: t.act.mats, minutes: t.act.min }, [id('game', 2), id('tip', 4)], t.act.tn);
  add('real_world', '응용문제', { title: t.real[0], scenario: { icon: t.real[1], body: t.real[2] }, content: t.real[3] }, [id('real', 2), id('real', 3)]);
  add('advanced_problem', '응용문제', { title: '생각을 넓혀요', context: t.adv[0], challenge: t.adv[1], note: t.adv[2] }, [id('tip', 5)], t.adv[3]);
  add('exit_ticket', '정리', { title: '오늘 확인해요', items: t.exit, self: ['오늘 배운 것을 혼자 설명할 수 있어요', '조금 헷갈려요', '다시 배우고 싶어요'] }, []);
  const pts = s ? nk(s.summary).split('\n').filter(Boolean) : [t.real[3].replace(/\*\*/g, '**')];
  add('summary', '정리', { title: '오늘 배운 것', points: pts.concat(t.sum.story), arrows: t.sum.arrows }, [id('real', 1)]);
  add('self_assessment', '정리', { title: '스스로 점검해요', items: ['📚 지식·이해 — ' + t.self[0][0], '🔧 과정·기능 — ' + t.self[0][1], '💛 가치·태도 — ' + t.self[0][2]], prompts: [t.self[1]] }, [id('e', 3)]);
  add('next_lesson', '정리', { title: idx === keys.length - 1 ? '다음 단원엔' : '다음 시간엔', preview: nk(t.nextText || (s.next + '. ' + s.next_q)), emoji: t.next }, [id('c', 1)]);
  const meta = { grade: 6, subject: '수학', term: 2, unit: 6, unit_title: UT, n, title: t.title, std: STD[key] || STD7, duration_min: 40, lesson_format: t.fmt + ' · 2세대 19장(7요소)', theme: '생활 속 원기둥, 원뿔, 구', pages: PAGE[key] };
  if (Object.keys(srcNotes).length) meta.concept_src = srcNotes;
  if (s) { meta.live_url = LIVE + s.file; meta.source = DIR + s.file; } else meta.source = '지도서 374~375쪽 · 『수학』 136~137쪽 (자기주도 원문 없음)';
  LESSONS[key] = { meta, slides, extras: ex };
});

